production_options_function.source:
function(rhodes_target_options target)
    if(MSVC)
        target_compile_options(${target} PRIVATE /W4 /permissive- /fp:precise)
        if(RHODES_WARNINGS_AS_ERRORS)
            target_compile_options(${target} PRIVATE /WX)
        endif()
    else()
        target_compile_options(${target} PRIVATE -Wall -Wextra -Wpedantic -Wconversion -Wshadow)
        if(RHODES_WARNINGS_AS_ERRORS)
            target_compile_options(${target} PRIVATE -Werror)
        endif()
        if(RHODES_ENABLE_SANITIZERS)
            target_compile_options(${target} PRIVATE -fsanitize=address,undefined -fno-omit-frame-pointer)
            target_link_options(${target} PRIVATE -fsanitize=address,undefined)
        endif()
    endif()
endfunction()

highlight_and_geometry_invariants.header_static_assert:
static_assert([] {
    for (const auto& highlight : kKeyHighlights) {
        if (highlight.visible_path_count == 0 ||
            highlight.visible_path_count > highlight.visible_paths.size()) { return false; }
    }
    return true;
}(), "photo geometry must have bounded, closed visible contours");
